using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class InspectB2Sword {
 public static object Run(){var path=AssetDatabase.FindAssets("t:Model",new[]{"Assets/3DBattle/Boss2"}).Select(AssetDatabase.GUIDToAssetPath).First();var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path));g.hideFlags=HideFlags.HideAndDontSave;var camera=new GameObject("Sword inspect camera");var cam=camera.AddComponent<Camera>();var rt=new RenderTexture(500,700,24);var tex=new Texture2D(500,700,TextureFormat.RGB24,false);var active=RenderTexture.active;try{g.transform.position=new Vector3(1000,0,1000);var r=g.GetComponentInChildren<Renderer>();var bounds=r.bounds;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.gray;cam.orthographic=true;cam.orthographicSize=bounds.size.y*.65f;cam.transform.position=bounds.center+Vector3.back*3;cam.transform.LookAt(bounds.center);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,500,700),0,0);tex.Apply();System.IO.File.WriteAllBytes("Assets/3DBattle/Authoring~/B2SwordSource.png",tex.EncodeToPNG());var boss=UnityEngine.Object.FindObjectsByType<Animator>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(a=>a.name.StartsWith("Meshy_AI_lowpoly_paladin"));var hand=boss.GetComponentsInChildren<Transform>(true).First(t=>t.name=="RightHand");return new{bounds=bounds.ToString("F5"),modelScale=g.transform.localScale.ToString(),fingers=hand.GetComponentsInChildren<Transform>().Select(t=>new{t.name,pos=hand.InverseTransformPoint(t.position).ToString("F6")}),textures=r.sharedMaterial.GetTexturePropertyNames().Select(n=>new{name=n,texture=r.sharedMaterial.GetTexture(n)?.name})};}finally{RenderTexture.active=active;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(camera);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}
}
